1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const CURSE_SURCHARGE_RATE = 0.5;
4	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
5	const HIGH_ENCHANTMENT_THRESHOLD = 5;
6	const LOYALTY_DISCOUNT_RATE = 0.2;
7	const LOYALTY_THRESHOLD_YEARS = 2;
8	const FOLLOWUP_CONTRACT_DISCOUNT_RATE = 0.15;
9	const COMPONENT_BLOCK_BASE = 60;
10	const COMPONENT_BLOCK_SIZE = 3;
11	const DEDUCTIBLE_PER_DAMAGE = 100;
12	const CAP_MULTIPLIER = 2;
13	
14	const BASE_PREMIUM: Record<string, number> = {
15	  sword: 100,
16	  amulet: 60,
17	  staff: 80,
18	  potion: 40,
19	  rune: 25,
20	  moonstone: 25,
21	};
22	
23	const INSURANCE_VALUE: Record<string, number> = {
24	  sword: 1000,
25	  amulet: 600,
26	  staff: 800,
27	  potion: 400,
28	  rune: 250,
29	  moonstone: 250,
30	};
31	
32	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
33	
34	type Item = { type: string; cursed?: boolean; enchantment?: number };
35	type Customer = { yearsWithMHPCO: number };
36	type QuoteStep = { op: "quote"; items: Item[] };
37	type Damage = { itemType: string; amount: number };
38	type ClaimStep = {
39	  op: "claim";
40	  policy: number;
41	  incident: { cause: string; damages: Damage[] };
42	};
43	type Step = QuoteStep | ClaimStep;
44	type Scenario = { customer: Customer; steps: Step[] };
45	
46	type QuoteResult = { premium: number };
47	type ClaimResult = { payout: number; remainingCap: number };
48	type StepResult = QuoteResult | ClaimResult;
49	
50	type Policy = { items: Item[]; insuranceSum: number; cap: number; remainingCap: number };
51	
52	const countByType = (items: Item[]): Map<string, number> =>
53	  items.reduce(
54	    (counts, { type }) => counts.set(type, (counts.get(type) ?? 0) + 1),
55	    new Map<string, number>(),
56	  );
57	
58	const basePremiumForGroup = (type: string, count: number): number =>
59	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE
60	    ? COMPONENT_BLOCK_BASE
61	    : count * BASE_PREMIUM[type];
62	
63	const basePremiumForItems = (items: Item[]): number =>
64	  [...countByType(items)].reduce(
65	    (sum, [type, count]) => sum + basePremiumForGroup(type, count),
66	    0,
67	  );
68	
69	const surchargeRateForItem = (item: Item): number =>
70	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
71	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
72	
73	const itemSurcharges = (items: Item[]): number =>
74	  items.reduce(
75	    (sum, item) => sum + BASE_PREMIUM[item.type] * surchargeRateForItem(item),
76	    0,
77	  );
78	
79	const roundUpForInsurer = (premium: number): number => Math.ceil(premium);
80	const roundDownForInsurer = (payout: number): number => Math.floor(payout);
81	
82	const loyaltyDiscountRate = (customer: Customer): number =>
83	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? LOYALTY_DISCOUNT_RATE : 0;
84	
85	const followupDiscountRate = (quoteIndex: number): number =>
86	  quoteIndex > 0 ? FOLLOWUP_CONTRACT_DISCOUNT_RATE : 0;
87	
88	const withPolicyWideModifiers = (
89	  base: number,
90	  customer: Customer,
91	  quoteIndex: number,
92	): number =>
93	  base +
94	  base * FIRST_INSURANCE_SURCHARGE_RATE -
95	  base * loyaltyDiscountRate(customer) -
96	  base * followupDiscountRate(quoteIndex);
97	
98	const quotePremium = (
99	  { items }: QuoteStep,
100	  customer: Customer,
101	  quoteIndex: number,
102	): number =>
103	  roundUpForInsurer(
104	    withPolicyWideModifiers(basePremiumForItems(items), customer, quoteIndex) +
105	      itemSurcharges(items),
106	  ) + PROCESSING_FEE;
107	
108	const insuranceSumFor = (items: Item[]): number =>
109	  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);
110	
111	const policyFrom = (items: Item[]): Policy => {
112	  const insuranceSum = insuranceSumFor(items);
113	  const cap = insuranceSum * CAP_MULTIPLIER;
114	  return { items, insuranceSum, cap, remainingCap: cap };
115	};
116	
117	const payoutForDamage = (amount: number): number =>
118	  roundDownForInsurer(Math.max(0, amount - DEDUCTIBLE_PER_DAMAGE));
119	
120	const processClaim = (policy: Policy, step: ClaimStep): { result: ClaimResult; policy: Policy } => {
121	  const totalPayout = step.incident.damages.reduce(
122	    (sum, damage) => sum + payoutForDamage(damage.amount),
123	    0,
124	  );
125	  const actualPayout = Math.min(totalPayout, policy.remainingCap);
126	  const newPolicy = { ...policy, remainingCap: policy.remainingCap - actualPayout };
127	  return {
128	    result: { payout: actualPayout, remainingCap: newPolicy.remainingCap },
129	    policy: newPolicy,
130	  };
131	};
132	
133	export const runScenario = ({ customer, steps }: Scenario): { results: StepResult[] } => {
134	  const results: StepResult[] = [];
135	  const policies = new Map<number, Policy>();
136	  let quoteIndex = 0;
137	  steps.forEach((step, index) => {
138	    if (step.op === "quote") {
139	      results.push({ premium: quotePremium(step, customer, quoteIndex) });
140	      policies.set(index, policyFrom(step.items));
141	      quoteIndex += 1;
142	    } else {
143	      const policy = policies.get(step.policy)!;
144	      const { result, policy: updated } = processClaim(policy, step);
145	      policies.set(step.policy, updated);
146	      results.push(result);
147	    }
148	  });
149	  return { results };
150	};
