const processClaim = (policy: Policy, step: ClaimStep): { result: ClaimResult; policy: Policy } => {
  const totalPayout = step.incident.damages.reduce(
    (sum, damage) => sum + payoutForDamage(damage.amount),
    0,
  );
  const actualPayout = Math.min(totalPayout, policy.remainingCap);
  const newPolicy = { ...policy, remainingCap: policy.remainingCap - actualPayout };
  return {
    result: { payout: actualPayout, remainingCap: newPolicy.remainingCap },
    policy: newPolicy,
  };
};

