const totalPayoutFor = (damages: Damage[]): number =>
  damages.reduce((sum, damage) => sum + payoutForDamage(damage.amount), 0);

const applyClaim = (policy: Policy, step: ClaimStep): Policy => {
  const payout = Math.min(totalPayoutFor(step.incident.damages), policy.remainingCap);
  return { ...policy, remainingCap: policy.remainingCap - payout };
};

const claimResultFor = (before: Policy, after: Policy): ClaimResult => ({
  payout: before.remainingCap - after.remainingCap,
  remainingCap: after.remainingCap,
});

export const runScenario = ({ customer, steps }: Scenario): { results: StepResult[] } => {
  const results: StepResult[] = [];
  const policies = new Map<number, Policy>();
  let quoteIndex = 0;
  steps.forEach((step, index) => {
    if (step.op === "quote") {
      results.push({ premium: quotePremium(step, customer, quoteIndex) });
      policies.set(index, policyFrom(step.items));
      quoteIndex += 1;
    } else {
      const before = policies.get(step.policy)!;
      const after = applyClaim(before, step);
      policies.set(step.policy, after);
      results.push(claimResultFor(before, after));
    }
  });
  return { results };
};
